function toggleMenu(){document.querySelector('.nav-links').classList.toggle('active')}
async function handlePaste(){try{const t=await navigator.clipboard.readText();const i=document.getElementById('urlInput');i.value=t;i.focus()}catch(e){console.error('Clipboard error:',e);alert('Could not paste. Please paste manually.')}}
async function handleDownload(e){e.preventDefault();const url=document.getElementById('urlInput').value;const loading=document.getElementById('loading');const result=document.getElementById('result');const error=document.getElementById('error');if(!url)return;try{const p=new URL(url);if(!['http:','https:'].includes(p.protocol)){error.innerText='Please enter a valid HTTP or HTTPS URL.';error.style.display='block';return}}catch(e){error.innerText='Please enter a valid URL (e.g., https://www.youtube.com/watch?v=...)';error.style.display='block';return}loading.style.display='block';result.style.display='none';error.style.display='none';try{const f=new FormData();f.append('url',url);const res=await fetch('/preview',{method:'POST',body:f});const rawText=await res.text();let data;try{data=JSON.parse(rawText)}catch(_){throw new Error('Server error. Please try again later.')}if(!res.ok)throw new Error(data.detail||'Failed to fetch video');document.getElementById('thumb').src=data.thumbnail;document.getElementById('videoTitle').innerText=data.title;document.getElementById('uploader').innerText=data.uploader||'Unknown';document.getElementById('views').innerText=data.view_count||'N/A';document.getElementById('duration').innerText=data.duration||'N/A';result.style.display='block'}catch(err){error.innerText=err.message;error.style.display='block'}finally{loading.style.display='none'}}
async function triggerDownload(format){const status=document.getElementById('loading');status.innerText='Downloading...';status.style.display='block';try{const f=new FormData();f.append('url',document.getElementById('urlInput').value);f.append('format',format);const res=await fetch('/download',{method:'POST',body:f});if(!res.ok){const t=await res.text();let msg='Download failed. Please try again.';try{const j=JSON.parse(t);msg=j.detail||msg}catch(_){if(t&&t.length<200)msg=t}throw new Error(msg)}const blob=await res.blob();const url=window.URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;const cd=res.headers.get('Content-Disposition');let filename='video.mp4';if(cd&&cd.indexOf('attachment')!==-1){const u8=/filename\*=UTF-8''([^;\n]*)/i.exec(cd);if(u8&&u8[1]){filename=decodeURIComponent(u8[1].replace(/['"]/g,''))}else{const fm=/filename[^;=\n]*=((['"]).*?\2|[^;\n]*)/.exec(cd);if(fm&&fm[1])filename=fm[1].replace(/['"]/g,'')}}if(format==='audio'&&!filename.endsWith('.m4a')&&!filename.endsWith('.mp3'))filename=filename.replace(/\.[^/.]+$/,'.m4a');a.download=filename;document.body.appendChild(a);a.click();a.remove();if(typeof window.gtag==='function')window.gtag('event','video_download',{'event_category':'Engagement','event_label':format,'file_name':filename});status.innerText='Download Complete!';setTimeout(()=>{status.style.display='none';status.innerText='Processing...'},3000)}catch(err){alert('Error: '+err.message);status.style.display='none'}}
